// Format conversation history for AI
const history = $input.all();
const contextData = $('Build Context').item.json;

const messages = [];
let latestVersion = 0;
let originalRequirements = '';

// Process all messages
for (const item of history) {
  const fields = item.json.fields;

  // Track latest version
  if (fields.design_version > latestVersion) {
    latestVersion = fields.design_version;
  }

  // Capture original requirements
  if (fields.type === 'pm' && fields.requirements) {
    originalRequirements = fields.requirements;
  }

  // Build message for AI context
  let content = fields.content;

  // For AI responses, include snippet of HTML generated
  if (fields.type === 'ai' && fields.html_output) {
    content += `\n\n[Generated HTML v${fields.design_version}]: ${fields.html_output.substring(0, 300)}...`;
  }

  messages.push({
    role: fields.role,
    content: content,
    type: fields.type,
    version: fields.design_version
  });
}

// Build context summary
const contextSummary = `
=== CONVERSATION CONTEXT ===
Chat ID: ${contextData.chatId}
Original Requirements: ${originalRequirements || 'N/A'}
Current Version: ${latestVersion}
Total Messages: ${messages.length}

=== CONVERSATION HISTORY ===
${messages.map((m, i) => `[${i + 1}] ${m.type.toUpperCase()} (v${m.version}): ${m.content}`).join('\n\n')}

=== NEW REQUEST ===
${contextData.inputType === 'chat' ? 'User: ' + contextData.userMessage : 'PM Requirements: ' + contextData.requirements}
`;

return {
  json: {
    messages: messages,
    contextSummary: contextSummary,
    latestVersion: latestVersion,
    newVersion: latestVersion + 1,
    originalRequirements: originalRequirements,
    chatId: contextData.chatId,
    inputType: contextData.inputType,
    userMessage: contextData.userMessage,
    requirements: contextData.requirements
  }
};

// Extract HTML from AI response
const aiResponse = $input.first().json.output;
const contextData = $('Format History for AI').item.json;

// Extract HTML code from markdown
const htmlMatch = aiResponse.match(/```html\n([\s\S]*?)```/);
const rawHtml = htmlMatch ? htmlMatch[1] : aiResponse;

// Build complete HTML
const completeHtml = `
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>UX Preview v${contextData.newVersion} - ${contextData.chatId}</title>
    <script src="https://cdn.tailwindcss.com"></script>
</head>
<body>
    ${rawHtml}

    <!-- Version Watermark -->
    <div style="position: fixed; bottom: 10px; right: 10px; background: rgba(0,0,0,0.7); color: white; padding: 8px 12px; border-radius: 4px; font-size: 11px; font-family: monospace; z-index: 9999;">
        v${contextData.newVersion} | Chat: ${contextData.chatId.slice(0, 8)}... | ${new Date().toLocaleTimeString()}
    </div>
</body>
</html>
`;

return {
  json: {
    html: completeHtml,
    rawHtml: rawHtml,
    chatId: contextData.chatId,
    version: contextData.newVersion,
    timestamp: new Date().toISOString(),
    aiResponse: aiResponse.replace(htmlMatch ? htmlMatch[0] : '', '').trim() // AI's explanation without HTML
  }
};
